// Input — generated by uidx codegen from its .uidx file. Do not edit; change the file.

import { type CSSProperties, type ReactNode, useRef } from 'react'
import { useElementEvent } from './runtime'
import './input.css'

export interface InputProps {
  /** What the field asks for. */
  label?: string
  /** A hint shown while the field is empty. */
  placeholder?: string
  /** A sentence under the field. */
  helpText?: string
  /** What the field holds. */
  value?: string
  /** Not editable, dimmed. */
  disabled?: boolean
  /** Fires when an edit is committed. */
  onChange?: (detail: unknown) => void
  /** An icon before the text. */
  prefix?: ReactNode
  /** An icon after the text. */
  suffix?: ReactNode
  /** Extra class names for the root element. */
  className?: string
  /** Inline style for the root element. */
  style?: CSSProperties
}

function InputBase({ label, placeholder, helpText, value, disabled, onChange, prefix, suffix, className, style }: InputProps) {
  const ref = useRef<HTMLElement>(null)
  useElementEvent(ref, 'sl-change', onChange)
  return (
    <sl-input ref={ref} className={className} style={style} label={label} placeholder={placeholder} help-text={helpText} value={value} disabled={!!disabled}>
      {prefix !== undefined ? <span slot="prefix" data-slot="prefix">{prefix}</span> : null}
      {suffix !== undefined ? <span slot="suffix" data-slot="suffix">{suffix}</span> : null}
    </sl-input>
  )
}

export const Input = InputBase
